464	fn complete_value_candidates(
465	    value: &OsStr,
466	    completer: &dyn ValueCandidates,
467	) -> Vec<CompletionCandidate> {
468	    debug!("complete_value_candidates: value={value:?}");
469	
470	    let mut values = completer.candidates();
471	    values.retain(|comp| comp.get_value().starts_with(&value.to_string_lossy()));
472	    values
473	}
474	
475	fn complete_candidates_str(
476	    value: &str,
477	    mut values: Vec<CompletionCandidate>,
478	) -> Vec<CompletionCandidate> {
479	    debug!("complete_candidates_str: value={value:?}");
480	
481	    values.retain(|comp| comp.get_value().starts_with(value));
482	    values
483	}
