552	/// Gets all the short options, their visible aliases and flags of a [`clap::Command`].
553	/// Includes `h` and `V` depending on the [`clap::Command`] settings.
554	fn shorts_and_visible_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
555	    debug!("shorts: name={}", p.get_name());
556	
557	    p.get_arguments()
558	        .filter_map(|a| {
559	            a.get_short_and_visible_aliases().map(|shorts| {
560	                shorts.into_iter().map(|s| {
561	                    populate_arg_candidate(CompletionCandidate::new(s.to_string()), a).help(
562	                        a.get_help()
563	                            .cloned()
564	                            .or_else(|| a.get_long().map(|long| format!("--{long}").into())),
565	                    )
566	                })
567	            })
568	        })
569	        .flatten()
570	        .collect()
571	}
572	
573	fn populate_arg_candidate(candidate: CompletionCandidate, arg: &clap::Arg) -> CompletionCandidate {
574	    candidate
575	        .help(arg.get_help().cloned())
576	        .id(Some(format!("arg::{}", arg.get_id())))
577	        .tag(Some(
578	            arg.get_help_heading()
579	                .unwrap_or("Options")
580	                .to_owned()
581	                .into(),
582	        ))
583	        .display_order(Some(arg.get_display_order()))
584	        .hide(arg.is_hide_set())
585	}
