587	/// Get the possible values for completion
588	fn possible_values(
589	    a: &clap::Arg,
590	) -> Option<Box<dyn Iterator<Item = clap::builder::PossibleValue> + '_>> {
591	    if !a.get_num_args().expect("built").takes_values() {
592	        None
593	    } else {
594	        a.get_value_parser().possible_values()
595	    }
596	}
