// Collapse the several spellings of an argument the way they are shown:
// every long spelling (the primary name and each visible alias) is its own
// candidate, while short spellings share one slot with the long spellings.
// Whichever style is generated first wins the shared slot (e.g. at `-` the
// short spelling comes first), preserving the established presentation.
let mut kept_long = std::collections::HashSet::<&String>::new();
let mut kept_short = std::collections::HashSet::<&String>::new();
let mut seen_long_spellings = std::collections::HashSet::<(&String, OsString)>::new();
completions.retain(|a| {
    let Some(id) = a.get_id() else {
        return true;
    };
    if a.get_value().starts_with("--") {
        kept_short.contains(id)
            || (kept_long.insert(id)
                && seen_long_spellings.insert((id, a.get_value().to_owned())))
    } else {
        !kept_long.contains(id) && kept_short.insert(id)
    }
});

