/// Remove candidates for the other members of a non-multiple argument group
/// once one of its members is already present.
///
/// Only groups that disallow more than one member (`ArgGroup::multiple(false)`,
/// the default) are treated as exclusive, mirroring how the parser validates
/// them. Repeating the selected member is allowed (when the argument itself
/// permits it), so the candidate for the member in use is kept while every
/// other member's names and aliases are hidden. Positional values,
/// subcommands, and custom candidates are left untouched, as are candidates
/// belonging to other groups.
fn filter_exclusive_group_candidates(
    completions: &mut Vec<CompletionCandidate>,
    cmd: &clap::Command,
    used_args: &[clap::Id],
) {
    if used_args.is_empty() {
        return;
    }
    // Ids of every other member of each exclusive group that already has a
    // member on the command line.
    let mut excluded: std::collections::HashSet<clap::Id> = std::collections::HashSet::new();
    for used_id in used_args {
        for group in cmd.get_groups() {
            if !group.get_args().any(|id| id == used_id) || group.is_multiple() {
                continue;
            }
            excluded.extend(group.get_args().filter(|id| *id != used_id).cloned());
        }
    }
    if excluded.is_empty() {
        return;
    }
    completions.retain(|candidate| {
        let Some(arg_id) = candidate
            .get_id()
            .and_then(|id| id.strip_prefix("arg::"))
        else {
            return true;
        };
        !excluded.iter().any(|id| id.as_str() == arg_id)
    });
}

